import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
import { VitePWA } from "vite-plugin-pwa";

// Обычная сборка: PWA с манифестом и service worker (офлайн).
export default defineConfig({
  base: "./",
  plugins: [
    react(),
    VitePWA({
      registerType: "autoUpdate",
      injectRegister: "auto",
      includeAssets: ["icon.svg", "apple-touch-icon.png"],
      manifest: {
        name: "DietVika",
        short_name: "DietVika",
        description: "Порции методом рук: отмечай, что съела за день, по плану от специалиста.",
        lang: "ru",
        dir: "ltr",
        start_url: "./",
        scope: "./",
        display: "standalone",
        orientation: "portrait",
        background_color: "#EEF3EF",
        theme_color: "#3F9B5A",
        icons: [
          { src: "icon-192.png", sizes: "192x192", type: "image/png" },
          { src: "icon-512.png", sizes: "512x512", type: "image/png" },
          { src: "icon-512-maskable.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
          { src: "icon.svg", sizes: "any", type: "image/svg+xml" },
        ],
      },
      workbox: {
        globPatterns: ["**/*.{js,css,html,svg,png,woff2}"],
        navigateFallback: "index.html",
        runtimeCaching: [
          {
            urlPattern: /^https:\/\/fonts\.(googleapis|gstatic)\.com\/.*/i,
            handler: "CacheFirst",
            options: {
              cacheName: "google-fonts",
              expiration: { maxEntries: 20, maxAgeSeconds: 60 * 60 * 24 * 365 },
              cacheableResponse: { statuses: [0, 200] },
            },
          },
        ],
      },
    }),
  ],
});

vite.single.config.ts:
import { readFileSync } from "node:fs";
import { defineConfig, type Plugin } from "vite";
import react from "@vitejs/plugin-react";
import { viteSingleFile } from "vite-plugin-singlefile";

// Превью: всё в одном HTML-файле, без service worker и манифеста.
// Результат: dist-single/index.html (иконка встраивается как data: URI).
const inlineIcon = (): Plugin => ({
  name: "dietvika-inline-icon",
  transformIndexHtml(html) {
    const svg = readFileSync(new URL("./public/icon.svg", import.meta.url), "utf8").trim();
    return html
      .replace(/<link rel="icon"[^>]*>/, `<link rel="icon" type="image/svg+xml" href="data:image/svg+xml,${encodeURIComponent(svg)}" />`)
      .replace(/\s*<link rel="apple-touch-icon"[^>]*>/, "");
  },
});

export default defineConfig({
  base: "./",
  publicDir: false,
  plugins: [react(), inlineIcon(), viteSingleFile()],
  build: { outDir: "dist-single", emptyOutDir: true },
});

scripts/csv-to-foods.mjs:
// Конвертирует справочник продуктов (CSV, ";" , UTF-8 BOM) в src/data/foods.json.
// Запуск: npm run foods   (или: node scripts/csv-to-foods.mjs [путь-к-csv])
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const src = process.argv[2] ?? resolve(root, "src/data/справочник-продуктов.csv");
const out = resolve(root, "src/data/foods.json");

const GROUPS = {
  "Фрукты": "fruit",
  "Овощи": "veg",
  "Зерновые": "grain",
  "Белок": "prot",
  "Молочные": "dairy",
  "Свободный приём пищи": "free",
};

const text = readFileSync(src, "utf8").replace(/^﻿/, "");
const [header, ...rows] = text.split(/\r?\n/).filter((l) => l.trim());
if (!header.startsWith("Группа;")) throw new Error("Неожиданный заголовок CSV: " + header);

/** "3 oz-eq" → 3, "≈ 1,5 oz-eq" → 1.5, "1 cup" → 1, "неделя" → 1 */
function parseCount(s, g) {
  if (g === "free") return 1;
  const m = /(\d+(?:[.,]\d+)?)/.exec(s);
  return m ? Number(m[1].replace(",", ".")) : NaN;
}

// Заметки видит клиент: убираем служебные пометки и американские единицы.
function clientNote(note) {
  return note
    .replace(/или в белке — Вика решает, куда считать/, "можно считать и в белке")
    .replace(/^Великобритания.*EUFIC.*$/, "")
    .replace(/^по британскому гиду.*$/, "")
    .replace(/\s*\(как у EUFIC\)/, "")
    .replace(/миндальное и овсяное USDA не считает молочными/, "миндальное и овсяное не считаются молочными")
    .replace(/(\d+(?:[.,]\d+)?)\s*(oz-eq|cup)/g, "$1 порции")
    .trim();
}

const foods = [];
const skipped = [];
for (const line of rows) {
  // в заметке тоже бывает «;», поэтому всё после 5-го поля — заметка
  const cells = line.split(";");
  const [group, name, hand, grams, counts] = cells.slice(0, 5).map((x) => x.trim());
  const note = cells.slice(5).join(";").trim();
  const g = GROUPS[group];
  const why =
    !g ? "группа не считается" :
    hand === "?" ? "порция не уточнена" :
    /не молочное/i.test(counts) ? "не молочное" :
    hand === "—" ? "нет порции" : "";
  if (why) { skipped.push(`${group} / ${name}: ${why}`); continue; }
  const q = parseCount(counts, g);
  if (!Number.isFinite(q) || q <= 0) { skipped.push(`${group} / ${name}: не разобрано «${counts}»`); continue; }
  const food = { g, name, hand: hand.replace(/\s*\(по EUFIC\)/, ""), q };
  if (grams && grams !== "—") food.grams = grams;
  const shown = clientNote(note);
  if (shown) food.note = shown;
  foods.push(food);
}

writeFileSync(out, JSON.stringify(foods, null, 1) + "\n");
console.log(`foods.json: ${foods.length} продуктов`);
if (skipped.length) console.log("Пропущено:\n  " + skipped.join("\n  "));

scripts/make-icons.mjs:
// Рисует иконки приложения (концентрические кольца групп) без внешних зависимостей.
// Запуск: npm run icons  → public/icon-192.png, icon-512.png, icon-512-maskable.png, apple-touch-icon.png, icon.svg
import { writeFileSync } from "node:fs";
import { deflateSync } from "node:zlib";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const pub = resolve(dirname(fileURLToPath(import.meta.url)), "../public");
const BG = "#EEF3EF";
const TRACK = "#DCE6E0";
// фрукты, овощи, зерновые, белок, молочные (снаружи внутрь) и доля заполнения
const RINGS = [["#E2483D", 0.82], ["#3F9B5A", 0.7], ["#D98B1F", 0.9], ["#7A4BB3", 0.6], ["#3A86C8", 0.76]];

const hex = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));

function crc32(buf) {
  let c, crc = 0xffffffff;
  for (let n = 0; n < buf.length; n++) {
    c = (crc ^ buf[n]) & 0xff;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    crc = (crc >>> 8) ^ c;
  }
  return (crc ^ 0xffffffff) >>> 0;
}
function chunk(type, data) {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const td = Buffer.concat([Buffer.from(type), data]);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(td));
  return Buffer.concat([len, td, crc]);
}
function png(size, px) {
  const raw = Buffer.alloc((size * 4 + 1) * size);
  for (let y = 0; y < size; y++) {
    raw[y * (size * 4 + 1)] = 0;
    px.copy(raw, y * (size * 4 + 1) + 1, y * size * 4, (y + 1) * size * 4);
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(size, 0); ihdr.writeUInt32BE(size, 4);
  ihdr[8] = 8; ihdr[9] = 6; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk("IHDR", ihdr), chunk("IDAT", deflateSync(raw)), chunk("IEND", Buffer.alloc(0)),
  ]);
}

/** scale: доля размера, которую занимают кольца; rounded: скруглённый фон (не для maskable) */
function draw(size, scale, rounded) {
  const px = Buffer.alloc(size * size * 4);
  const SS = 4, c = size / 2, R = (size / 2) * scale, w = R / 7, gap = R / 4.7;
  const corner = size * 0.22;
  const bg = hex(BG), track = hex(TRACK);
  const sample = (x, y) => {
    // фон со скруглёнными углами
    if (rounded) {
      const dx = Math.max(corner - x, 0, x - (size - corner)), dy = Math.max(corner - y, 0, y - (size - corner));
      if (dx * dx + dy * dy > corner * corner) return null;
    }
    const dx = x - c, dy = y - c, d = Math.hypot(dx, dy);
    let ang = Math.atan2(dx, -dy) / (2 * Math.PI); if (ang < 0) ang += 1;
    for (let i = 0; i < RINGS.length; i++) {
      const r = R - w / 2 - i * gap;
      if (Math.abs(d - r) <= w / 2) return ang <= RINGS[i][1] ? hex(RINGS[i][0]) : track;
      // скруглённые концы дуги
      const a = RINGS[i][1] * 2 * Math.PI;
      for (const t of [0, a]) {
        const ex = c + r * Math.sin(t), ey = c - r * Math.cos(t);
        if (Math.hypot(x - ex, y - ey) <= w / 2) return hex(RINGS[i][0]);
      }
    }
    return bg;
  };
  for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
    let r = 0, g = 0, b = 0, a = 0;
    for (let sy = 0; sy < SS; sy++) for (let sx = 0; sx < SS; sx++) {
      const col = sample(x + (sx + 0.5) / SS, y + (sy + 0.5) / SS);
      if (col) { r += col[0]; g += col[1]; b += col[2]; a++; }
    }
    const o = (y * size + x) * 4;
    if (a) { px[o] = r / a; px[o + 1] = g / a; px[o + 2] = b / a; }
    px[o + 3] = Math.round((a / (SS * SS)) * 255);
  }
  return png(size, px);
}

writeFileSync(resolve(pub, "icon-192.png"), draw(192, 0.78, true));
writeFileSync(resolve(pub, "icon-512.png"), draw(512, 0.78, true));
writeFileSync(resolve(pub, "icon-512-maskable.png"), draw(512, 0.6, false));
writeFileSync(resolve(pub, "apple-touch-icon.png"), draw(180, 0.72, false));

// SVG-версия (фавикон)
const R = 50 * 0.78, w = R / 7, gap = R / 4.7;
const arcs = RINGS.map(([col, p], i) => {
  const r = R - w / 2 - i * gap, L = 2 * Math.PI * r;
  return `<circle cx="50" cy="50" r="${r.toFixed(2)}" fill="none" stroke="${TRACK}" stroke-width="${w.toFixed(2)}"/>` +
    `<circle cx="50" cy="50" r="${r.toFixed(2)}" fill="none" stroke="${col}" stroke-width="${w.toFixed(2)}" stroke-linecap="round" stroke-dasharray="${(p * L).toFixed(2)} ${L.toFixed(2)}" transform="rotate(-90 50 50)"/>`;
}).join("");
writeFileSync(resolve(pub, "icon.svg"),
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" rx="22" fill="${BG}"/>${arcs}</svg>\n`);
console.log("Иконки готовы в public/");

