// Калькулятор для специалиста: расход энергии (TEE) по NASEM 2023 для взрослых 19+,
// нижняя граница BMR по Mifflin–St Jeor и подбор уровня плана USDA.
// Клиенту эти числа не показываются.

import { LEVELS, MAX_LEVEL, MIN_LEVEL } from "./plan";

export type Sex = "m" | "f";
export type Activity = "inactive" | "low" | "active" | "very";
export type Goal = "maintain" | "lose";

export const ACTIVITY_LABEL: Record<Activity, string> = {
  inactive: "Неактивный",
  low: "Малоактивный",
  active: "Активный",
  very: "Очень активный",
};

// TODO: коэффициенты сверить с письмом Вики «Формулы BMR и таблица PAL».
// NASEM 2023, взрослые 19+: TEE = a + b·A + c·H + d·W (A — годы, H — см, W — кг).
const NASEM: Record<Sex, Record<Activity, [number, number, number, number]>> = {
  m: {
    inactive: [753.07, -10.83, 6.5, 14.1],
    low: [581.47, -10.83, 8.3, 14.94],
    active: [1004.82, -10.83, 6.52, 15.91],
    very: [-517.88, -10.83, 15.61, 19.11],
  },
  f: {
    inactive: [584.9, -7.01, 5.72, 11.71],
    low: [575.77, -7.01, 6.6, 12.14],
    active: [710.25, -7.01, 6.54, 12.34],
    very: [511.83, -7.01, 9.07, 12.56],
  },
};

export function teeNasem(sex: Sex, act: Activity, age: number, heightCm: number, weightKg: number): number {
  const [a, b, c, d] = NASEM[sex][act];
  return a + b * age + c * heightCm + d * weightKg;
}

/** Mifflin–St Jeor: только как нижняя граница при снижении веса */
export function bmrMifflin(sex: Sex, age: number, heightCm: number, weightKg: number): number {
  return 10 * weightKg + 6.25 * heightCm - 5 * age + (sex === "m" ? 5 : -161);
}

export const LOSS_DEFICIT = 500;
export const LOSS_FLOOR = 1600;

export interface Suggestion {
  tee: number;
  bmr: number;
  /** целевая калорийность до округления к уровню */
  target: number;
  level: number;
  note: string;
}

const clampLevel = (k: number) => Math.min(MAX_LEVEL, Math.max(MIN_LEVEL, k));

export function suggestLevel(sex: Sex, act: Activity, age: number, h: number, w: number, goal: Goal): Suggestion {
  const tee = teeNasem(sex, act, age, h, w);
  const bmr = bmrMifflin(sex, age, h, w);
  if (goal === "maintain") {
    const level = clampLevel(Math.round(tee / 200) * 200);
    return { tee, bmr, target: tee, level: nearest(level), note: "Поддержание: расход округлён до ближайшего уровня." };
  }
  const raw = tee - LOSS_DEFICIT;
  const target = Math.max(raw, bmr, LOSS_FLOOR);
  // округляем ВНИЗ до уровня таблицы (шаг 200)
  const level = clampLevel(Math.floor(target / 200) * 200);
  const why =
    target === raw ? `расход − ${LOSS_DEFICIT}` :
    target === bmr ? "подняли до BMR" : `подняли до минимума ${LOSS_FLOOR}`;
  return { tee, bmr, target, level: nearest(level), note: `Снижение веса: ${why}, округлено вниз до уровня.` };
}

function nearest(k: number): number {
  return LEVELS.includes(k) ? k : LEVELS.reduce((a, l) => (Math.abs(l - k) < Math.abs(a - k) ? l : a));
}

src/plan.ts:
// План клиента: уровень USDA, цели по группам, вода, лимит свободного приёма пищи.
// План приходит ссылкой от специалиста: #plan=<base64url(JSON)>, сервера нет.

import plansData from "./data/plans-usda-2020.json";
import { addDays, isISODate, today, type ISODate } from "./dates";
import { GROUP_IDS, WATER, type GroupId } from "./units";
import { KEYS, readJSON, writeJSON } from "./storage";

export type Goals = Record<GroupId, number>;

export interface Plan {
  v: 1;
  client: string;
  specialist: string;
  kcal: number;
  start: ISODate;
  goals?: Partial<Goals>;
  water?: number;
  /** вегетарианский план: белок ×1,5 к обычной цели (если Вика не задала число сама) */
  veg?: boolean;
}
// Старые ссылки могли содержать freeLimit — поле игнорируется:
// у свободного приёма пищи нет лимита (решение Вики 15.10).

interface UsdaPlan {
  kcal: number;
  daily: { fruit_cup: number; veg_cup: number; grain_ozeq: number; protein_ozeq: number; dairy_cup: number };
}

const PLANS = (plansData as { plans: UsdaPlan[] }).plans;
export const LEVELS: number[] = PLANS.map((p) => p.kcal).sort((a, b) => a - b);
export const MIN_LEVEL = LEVELS[0];
export const MAX_LEVEL = LEVELS[LEVELS.length - 1];

/** Номер уровня для клиента (1…12) — ккал клиенту не показываем */
export function levelNumber(kcal: number): number {
  return LEVELS.indexOf(snapLevel(kcal)) + 1;
}

export function snapLevel(kcal: number): number {
  let best = LEVELS[0];
  for (const l of LEVELS) if (Math.abs(l - kcal) < Math.abs(best - kcal)) best = l;
  return best;
}

/** Цели по таблице USDA для уровня */
export function tableGoals(kcal: number): Goals {
  const p = PLANS.find((x) => x.kcal === snapLevel(kcal))!;
  return {
    fruit: p.daily.fruit_cup,
    veg: p.daily.veg_cup,
    grain: p.daily.grain_ozeq,
    prot: p.daily.protein_ozeq,
    dairy: p.daily.dairy_cup,
  };
}

export const VEG_PROTEIN_FACTOR = 1.5;

/** Цели по таблице с учётом вегетарианского плана (белок ×1,5, округление до 0,5) */
export function suggestedGoals(kcal: number, veg: boolean): Goals {
  const base = tableGoals(kcal);
  if (veg) base.prot = Math.round(base.prot * VEG_PROTEIN_FACTOR * 2) / 2;
  return base;
}

/** Итоговые дневные цели (таблица, вегетарианский белок, поправки специалиста), в единицах USDA */
export function planGoals(plan: Plan): Goals {
  const base = suggestedGoals(plan.kcal, !!plan.veg);
  for (const g of GROUP_IDS) {
    const o = plan.goals?.[g];
    if (typeof o === "number" && o >= 0) base[g] = o;
  }
  return base;
}

export function waterGoal(plan: Plan): number {
  return plan.water && plan.water > 0 ? plan.water : WATER.defaultGoal;
}

// ---------- ссылка ----------

function b64urlEncode(s: string): string {
  const bytes = new TextEncoder().encode(s);
  let bin = "";
  bytes.forEach((b) => (bin += String.fromCharCode(b)));
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function b64urlDecode(s: string): string {
  const b64 = s.replace(/-/g, "+").replace(/_/g, "/");
  const bin = atob(b64 + "===".slice((b64.length + 3) % 4));
  const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}

export function encodePlan(plan: Plan): string {
  return b64urlEncode(JSON.stringify(plan));
}

const str = (v: unknown, max: number) => (typeof v === "string" ? v.trim().slice(0, max) : "");
const num = (v: unknown, lo: number, hi: number) =>
  typeof v === "number" && Number.isFinite(v) && v >= lo && v <= hi ? v : undefined;

/** Проверяет и чистит план из ссылки или хранилища. null — если план негодный. */
export function sanitizePlan(raw: unknown): Plan | null {
  if (!raw || typeof raw !== "object") return null;
  const o = raw as Record<string, unknown>;
  if (o.v !== 1) return null;
  const kcal = num(o.kcal, 500, 5000);
  if (kcal === undefined) return null;
  const plan: Plan = {
    v: 1,
    client: str(o.client, 60),
    specialist: str(o.specialist, 60) || "Вика",
    kcal: snapLevel(kcal),
    start: isISODate(o.start) ? o.start : today(),
  };
  if (o.goals && typeof o.goals === "object") {
    const goals: Partial<Goals> = {};
    for (const g of GROUP_IDS) {
      const v = num((o.goals as Record<string, unknown>)[g], 0, 20);
      if (v !== undefined) goals[g] = v;
    }
    if (Object.keys(goals).length) plan.goals = goals;
  }
  if (o.veg === true) plan.veg = true;
  const water = num(o.water, 1, 20);
  if (water !== undefined) plan.water = Math.round(water);
  return plan;
}

export function decodePlan(encoded: string): Plan | null {
  try {
    return sanitizePlan(JSON.parse(b64urlDecode(encoded)));
  } catch {
    return null;
  }
}

/** Ссылка-приглашение на текущий адрес приложения */
export function inviteLink(plan: Plan): string {
  const base = window.location.href.split("#")[0];
  return `${base}#plan=${encodePlan(plan)}`;
}

/** Достаёт закодированный план из хэша вида #plan=... (или #/что-то?plan=...) */
export function planFromHash(hash: string): string | null {
  const m = /[#&?]plan=([A-Za-z0-9_-]+)/.exec(hash);
  return m ? m[1] : null;
}

// ---------- хранение ----------

export function loadPlan(): Plan | null {
  return sanitizePlan(readJSON<unknown>(KEYS.plan, null));
}

export function savePlan(plan: Plan): void {
  writeJSON(KEYS.plan, plan);
}

export function demoPlan(): Plan {
  return { v: 1, client: "Демо", specialist: "Вика", kcal: 1800, start: addDays(today(), -21) };
}

