// Единицы и подписи порций — всё, что клиент видит про «сколько», живёт здесь.
//
// Хранение всегда в единицах USDA: фрукты, овощи, молочные — cup; зерновые и белок — oz-eq.
// Показ клиенту идёт через активную систему счёта (UNIT_SYSTEM). Сейчас «usda»:
// 1 порция = 1 cup или 1 oz-eq, ладонь мяса = 3 порции белка.
// Если Вика выберет британский счёт (ладонь = 1 порция белка, см. docs/11), достаточно
// переключить ACTIVE_SYSTEM на "british": журнал, планы и ссылки менять не нужно.

export type GroupId = "fruit" | "veg" | "grain" | "prot" | "dairy";
export const GROUP_IDS: GroupId[] = ["fruit", "veg", "grain", "prot", "dairy"];

export type Shape = "fist" | "palm" | "cupped" | "glass" | "thumbs" | "drop" | "star";

export interface GroupInfo {
  id: GroupId;
  name: string;
  /** родительный падеж: «белка», «фруктов» */
  gen: string;
  shape: Shape;
  /** почему эта группа важна, совет */
  why: string;
}

export const GROUPS: Record<GroupId, GroupInfo> = {
  fruit: {
    id: "fruit", name: "Фрукты", gen: "фруктов", shape: "fist",
    why: "Клетчатка, витамин C и калий. Целые фрукты лучше сока: сок или смузи — не больше 150 мл в день (маленький стакан). Разные цвета каждый день.",
  },
  veg: {
    id: "veg", name: "Овощи", gen: "овощей", shape: "fist",
    why: "Объём тарелки и сытость. Чем больше цветов за неделю, тем лучше.",
  },
  grain: {
    id: "grain", name: "Зерновые", gen: "зерновых", shape: "cupped",
    why: "Главный источник энергии. Лучше цельнозерновые: гречка, овсянка, ржаной хлеб.",
  },
  prot: {
    id: "prot", name: "Белок", gen: "белка", shape: "palm",
    why: "Сытость и строительный материал. Рыба не реже 2 раз в неделю, красное и переработанное мясо реже. Орехи и семечки — тоже белок.",
  },
  dairy: {
    id: "dairy", name: "Молочные", gen: "молочного", shape: "glass",
