export const FREE = {
  name: "Свободный приём пищи",
  shape: "star" as Shape,
  hint: "1 отметка = один приём пищи на свой выбор.",
  why: "Любимая еда — часть нормальной жизни. Выбирай то, что действительно любишь, ешь с удовольствием и без спешки, а следующий приём пищи — снова по плану. Отметка нужна не для запрета, а чтобы видеть, как ты ешь.",
  kinds: [
    "Сладости, шоколад, конфеты",
    "Торт, десерт, мороженое",
    "Выпечка, круассаны",
    "Чипсы, картофель фри",
    "Жареное и фастфуд",
  ],
