/** Совет про добавленный сахар (лист «Сахар»: с плитки свободного приёма пищи и из «Советов») */
export const SUGAR = {
  line: "Добавленный сахар — не больше 30 г в день для взрослого",
  limit: "Не больше 30 г добавленного сахара в день — это примерно 6 чайных ложек. Одна чайная ложка ≈ 4–5 г. Сахар в целых фруктах, овощах и простом молоке сюда не входит.",
  hidden: [
    "Сладкие напитки, газировка и соки (даже 100% сок)",
    "Йогурты, творожки и сырки с добавками",
    "Соусы и кетчуп",
    "Хлопья для завтрака и мюсли",
    "Выпечка, печенье",
    "«Полезные» батончики",
  ],
  names: [
    "сахароза", "глюкоза", "фруктоза", "декстроза", "мальтоза", "патока",
    "сироп: глюкозный, глюкозно-фруктозный, кукурузный, агавы, кленовый",
    "мёд", "концентрат сока", "мальтодекстрин", "инвертный сироп", "тростниковый сахар",
  ],
  label: "Смотри строку «углеводы, в т. ч. сахара» в пересчёте на 100 г. Например, 10 г сахаров на 100 г йогурта — это 2 чайные ложки в маленькой баночке (≈ 100 г). Чем выше сахар в списке состава, тем его больше.",
};

// ---------- системы счёта ----------

interface UnitSystem {
  id: "usda" | "british";
  /** сколько порций для показа в 1 единице USDA (cup / oz-eq) */
  perUsda: Record<GroupId, number>;
  /** короткая подсказка «1 порция = …» */
  portion: Record<GroupId, string>;
  /** подробные меры руками (для экрана «Порции» и шторки) */
  hands: Record<GroupId, string[]>;
}

const USDA: UnitSystem = {
  id: "usda",
  perUsda: { fruit: 1, veg: 1, grain: 1, prot: 1, dairy: 1 },
  portion: {
    fruit: "1 порция = 1 кулак: средний фрукт, 2 мандарина или горсть ягод",
    veg: "1 порция = 1 кулак овощей или 2 кулака листового салата",
    grain: "1 порция = горсть готовой крупы (ладонь лодочкой) или 1 ломтик хлеба",
    prot: "Ладонь мяса или рыбы = 3 порции. Яйцо = 1 порция",
    dairy: "1 порция = стакан молока или кефира, или сыр размером с два больших пальца",
  },
  hands: {
    fruit: ["Кулак = 1 порция: яблоко, груша, апельсин", "Мелкие фрукты — 2 шт. (мандарины, киви)", "Ягоды, виноград — 1 кулак", "Сухофрукты — ½ кулака", "Сок или смузи — не больше 150 мл в день (маленький стакан)"],
    veg: ["Кулак = 1 порция: нарезанные овощи, брокколи, морковь", "Листовой салат: 2 кулака = 1 порция", "Тарелка овощного супа ≈ 1 порция"],
    grain: ["Горсть готовой крупы или макарон (ладонь лодочкой) = 1 порция", "Ломтик хлеба = 1 порция", "Кулак хлопьев или мюсли = 1 порция"],
    prot: ["Ладонь мяса, птицы или рыбы = 3 порции", "Яйцо = 1 порция", "Маленькая горсть орехов = 1 порция", "Кончик большого пальца арахисовой пасты = 1 порция"],
    dairy: ["Стакан молока, кефира или йогурта = 1 порция", "Сыр размером с два больших пальца (≈ 30–40 г) = 1 порция", "Творог — 3 столовые ложки с горкой (≈ 100 г) = 1 порция"],
  },
};

// Черновик британского счёта (docs/11): ладонь белка = 1 порция. Не включён.
const BRITISH: UnitSystem = {
  id: "british",
  perUsda: { fruit: 2, veg: 2, grain: 0.4, prot: 1 / 3, dairy: 1 },
  portion: {
    fruit: "1 порция = ½ кулака: небольшой фрукт или горсть ягод",
    veg: "1 порция = ½ кулака овощей или кулак листового салата",
    grain: "1 порция = две ладони лодочкой готовой крупы или 2 ломтика хлеба",
    prot: "1 порция = ладонь мяса или рыбы, или 3 яйца",
    dairy: "1 порция = стакан молока или кефира, или сыр размером с два больших пальца",
  },
  hands: USDA.hands,
};

const SYSTEMS = { usda: USDA, british: BRITISH };
const ACTIVE_SYSTEM: keyof typeof SYSTEMS = "usda";
const SYS = SYSTEMS[ACTIVE_SYSTEM];

/** Единицы USDA → порции для показа */
export function toDisplay(g: GroupId, usda: number): number {
  return usda * SYS.perUsda[g];
}
/** Порции для показа → единицы USDA (для записи в журнал) */
export function fromDisplay(g: GroupId, shown: number): number {
  return shown / SYS.perUsda[g];
}
export function portionHint(g: GroupId): string {
  return SYS.portion[g];
}
export function handLines(g: GroupId, veg = false): string[] {
  if (veg && g === "prot") return VEG_PROTEIN_HANDS;
  return SYS.hands[g];
}

// ---------- вегетарианский план ----------

export const VEG_WHY = "Сытость и строительный материал. Чередуй источники: яйца, бобовые, тофу, орехи и семечки — так белок получается полноценнее.";
export const VEG_NOTE = "Вегетарианцам белка нужно больше: примерно в полтора раза. Источники: яйца, бобовые, тофу, орехи и семечки.";

const VEG_PROTEIN_HANDS = [
  "Яйцо = 1 порция",
  "Фасоль, нут, чечевица: ¼ кулака варёных = 1 порция (кулак ≈ 4)",
  "Тофу: ¼ кулака = 1 порция; хумус: 2 столовые ложки = 1 порция",
  "Маленькая горсть орехов или ложка семечек = 1 порция",
  "Кончик большого пальца арахисовой пасты = 1 порция",
];

/** Мясо и рыба: в вегетарианском плане эти продукты не показываем (по началу названия) */
const MEAT_FISH = ["Курица", "Говядина", "Рыба", "Морепродукты", "Консервы рыбные", "Котлета", "Колбаса"];
/** Вегетарианские источники белка — первыми в списке */
const VEG_FIRST = ["Яйцо", "Фасоль", "Тофу", "Хумус", "Орехи", "Семечки", "Арахисовая"];

export function isMeatOrFish(name: string): boolean {
  return MEAT_FISH.some((m) => name.startsWith(m));
}

/** Порядок продуктов белка для вегетарианского плана: без мяса и рыбы, вегетарианские — первыми */
export function vegProteinOrder<T extends { name: string }>(foods: T[]): T[] {
  const rank = (n: string) => {
    const i = VEG_FIRST.findIndex((v) => n.startsWith(v));
    return i < 0 ? VEG_FIRST.length : i;
  };
  return foods.filter((f) => !isMeatOrFish(f.name)).sort((a, b) => rank(a.name) - rank(b.name));
}

// ---------- форматирование ----------

/** Округление до четверти */
export function q4(n: number): number {
  return Math.round(n * 4) / 4;
}

/** 1.5 → "1 ½", 0.25 → "¼", 3 → "3" */
export function fmt(n: number): string {
  const v = q4(Math.max(0, n));
  const w = Math.floor(v);
  const r = v - w;
  const f = r === 0.25 ? "¼" : r === 0.5 ? "½" : r === 0.75 ? "¾" : "";
  if (!f) return String(w);
  return w ? `${w} ${f}` : f;
}

/** Склонение: plural(2, ["порция","порции","порций"]). Дробные — родительный ед. ч. («1 ½ порции») */
export function plural(n: number, forms: [string, string, string]): string {
  const v = q4(Math.abs(n));
  if (!Number.isInteger(v)) return forms[1];
  const m10 = v % 10, m100 = v % 100;
  if (m10 === 1 && m100 !== 11) return forms[0];
  if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return forms[1];
  return forms[2];
}

export const PORTION: [string, string, string] = ["порция", "порции", "порций"];
export const GLASS: [string, string, string] = ["стакан", "стакана", "стаканов"];

/** "3 порции" */
export function portions(n: number): string {
  return `${fmt(n)} ${plural(n, PORTION)}`;
}

/** Винительный падеж: «отметить 1 порцию» */
export function portionsAcc(n: number): string {
  return `${fmt(n)} ${plural(n, ["порцию", "порции", "порций"])}`;
}

/** Глагол «остался/осталась/осталось» под число и род */
function left(n: number, gender: "m" | "f"): string {
  const v = q4(n);
  if (Number.isInteger(v) && v % 10 === 1 && v % 100 !== 11) return gender === "m" ? "Остался" : "Осталась";
  return "Осталось";
}

/** Подсказка «Что доесть»: сколько осталось и чем закрыть, языком рук. remainingUsda > 0 */
export function nudgeText(g: GroupId, remainingUsda: number, veg = false): string {
  const n = q4(toDisplay(g, remainingUsda));
  const shown = fmt(n);
  switch (g) {
    case "fruit":
      return `${left(n, "m")} ${shown} ${plural(n, ["кулак", "кулака", "кулаков"])} фруктов: например, яблоко, 2 мандарина или горсть ягод.`;
    case "veg":
      return `${left(n, "m")} ${shown} ${plural(n, ["кулак", "кулака", "кулаков"])} овощей: например, огурец с помидором, брокколи или тушёная капуста. Листового салата нужно 2 кулака на порцию.`;
    case "grain":
      return `${left(n, "f")} ${shown} ${plural(n, ["горсть", "горсти", "горстей"])} зерновых (ладонь лодочкой) или столько же ломтиков хлеба: например, гречка, овсянка или ржаной хлеб.`;
    case "prot": {
      if (veg) {
        const v = n < 1 ? "хватит одного яйца или маленькой горсти орехов." :
          `например, ${Math.ceil(n) > 3 ? "фасоль, нут или чечевица (кулак варёных ≈ 4 порции)" : `${Math.ceil(n)} ${plural(Math.ceil(n), ["яйцо", "яйца", "яиц"])}`}, тофу, хумус или маленькая горсть орехов.`;
        return `${left(n, "f")} ${shown} ${plural(n, PORTION)} белка: ${v}`;
      }
      if (ACTIVE_SYSTEM === "usda" && n >= 2.5) {
        const palms = Math.round((n / 3) * 2) / 2;
        return `${left(palms, "f")} ${fmt(palms)} ${plural(palms, ["ладонь", "ладони", "ладоней"])} белка: например, курица, рыба или индейка.`;
      }
      if (n < 1) return `${left(n, "f")} ${shown} порции белка: хватит одного яйца или маленькой горсти орехов.`;
      const eggs = Math.ceil(n);
      return `${left(n, "f")} ${shown} ${plural(n, PORTION)} белка: например, ${eggs} ${plural(eggs, ["яйцо", "яйца", "яиц"])} или маленькая горсть орехов (1 порция).`;
    }
    case "dairy":
      return `${left(n, "m")} ${shown} ${plural(n, GLASS)} молочного: например, кефир или молоко. Или сыр размером с два больших пальца.`;
  }
}

